details.returned_prompt:
{
  "high_level_description": "A documentary architectural photograph of a quiet tree-lined residential street on an overcast afternoon, showing a converted single-storey red-brick workshop housing a small architecture studio, with a vintage bicycle leaning against the wall beside a tall glazed door.",
  "compositional_deconstruction": {
    "background": "An overcast afternoon sky, flat and pale grey with diffused even daylight and neutral cool-toned white balance. Adjacent terraced red-brick buildings recede down the residential street on both sides, partially obscured by mature plane tree foliage. A distant parked car sits further down the street in soft focus. Mature plane trees line the street, their canopies casting dappled shadows across the facade and pavement. A narrow concrete footpath runs along the front of the building, scattered with a few fallen leaves. Deep focus throughout from foreground pavement to background street. Fine ambient grain consistent with documentary architectural photography.",
    "elements": [
      {
        "type": "obj",
        "desc": "Single-storey red-brick workshop facade filling most of the frame as the primary background element, weathered mortar joints between bricks, slight tonal variation across the brickwork in muted true reds. A low concrete plinth runs along the base at pavement level. Plain facade with no signage, no lettering, no house number plate."
      },
      {
        "type": "obj",
        "desc": "Tall glazed door set into the brick wall just left of frame centre, slim black steel frame around full-height glass panels. Through the glass, a dim interior is visible with a faint glimpse of drafting tables and paper rolls stacked inside."
      },
      {
        "type": "obj",
        "desc": "Vintage steel bicycle leaning against the brick wall to the right of the door, breaking the right-third of the frame. Worn brown leather saddle, slightly rusted chain, one flat tire splayed outward. Dark steel frame, upright handlebars."
      },
      {
        "type": "obj",
        "desc": "Low black iron railing running horizontally along the front of the building, separating the concrete footpath from a small strip of grass and exposed roots at the curb below."
      }
    ]
  }
}
